mapper.select:
SELECT COUNT(1)
FROM soldier_saving ss
WHERE ss.user_id = #{userId}

mapper.update:
UPDATE soldier_profile
SET rank_name = #{rankName}
WHERE user_id = #{userId}
  AND (rank_name IS NULL OR rank_name != #{rankName})

mapper.insert:
INSERT IGNORE INTO challenge_group (
    soldier_type,
    enlistment_year,
    enlistment_month
)
VALUES (
    #{soldierType},
    #{enlistmentYear},
    #{enlistmentMonth}
)

mapper.select:
SELECT cg.group_id
FROM challenge_group cg
WHERE cg.soldier_type = #{soldierType}
AND cg.enlistment_year = #{enlistmentYear}
AND cg.enlistment_month = #{enlistmentMonth}

mapper.insert:
INSERT IGNORE INTO challenge_member (
    group_id,
    user_id
)
VALUES (
    #{groupId},
    #{userId}
)
